from pathlib import Path
import json,re

tasks=[
 'DEV-PRED-ASTRA-AUTONOMOUS-REVIEWER-FIRSTFAIL-20261005',
 'DEV-PRED-ASTRA-AUTONOMOUS-FIRSTFAIL-LOG-20261005',
]
blobs=[]
for task in tasks:
    paths=[
        Path.home()/'.local/state/prediction-project-executor'/f'{task}.json',
        Path.home()/'prediction_research_prod'/'control/results'/task/'RESULT.json',
        Path.home()/'prediction_research_prod'/'control/results'/task/'stdout.log',
        Path.home()/'prediction_research_prod'/'control/results'/task/'stderr.log',
    ]
    for p in paths:
        if p.is_file():
            try:
                blobs.append((str(p),p.read_text(encoding='utf-8',errors='replace')))
            except Exception:
                pass

text='\n'.join(body for _,body in blobs)
lines=text.splitlines()
failure_test=''
for ln in lines:
    if '::' in ln and re.search(r'\bFAILED\b',ln):
        failure_test=ln.strip()
        break
if not failure_test:
    for ln in lines:
        if re.search(r'tests/.+::.+',ln) and ('AssertionError' in ln or 'ERROR' in ln):
            failure_test=ln.strip()
            break

details=[]
for ln in lines:
    s=ln.strip()
    if not s:
        continue
    if s.startswith('E ') or 'AssertionError' in s or 'assert ' in s or 'short test summary' in s:
        details.append(s)

def clean(s):
    s=re.sub(r'\s+',' ',s).strip()
    return s[:900]

failure_test=clean(failure_test or 'UNKNOWN')
detail=clean(' | '.join(details[-8:]) or 'NO_ASSERTION_TEXT_FOUND')
print('FIRST_FAILURE='+failure_test+' || DETAIL='+detail,flush=True)
raise SystemExit(42)
